import { WORKSPACE_CONNECTION_PROVIDERS as RUNTIME_WORKSPACE_CONNECTION_PROVIDERS, getWorkspaceConnectionProvider as getRuntimeWorkspaceConnectionProvider, listWorkspaceConnectionProviders as listRuntimeWorkspaceConnectionProviders, mergeWorkspaceConnectionProviders as mergeRuntimeWorkspaceConnectionProviders, } from "@agent-native/core/connections/runtime";
export * from "@agent-native/core/connections/runtime";
export const WORKSPACE_CONNECTION_PROVIDERS = [
    "slack",
    "github",
    "figma",
    "notion",
    "gmail",
    "google_calendar",
    "google_drive",
    "google_docs",
    "google_sheets",
    "google_slides",
    "hubspot",
    "salesforce",
    "jira",
    "sentry",
    "granola",
    "clips",
    "anthropic-managed-agents",
    "generic",
].map((id) => ({
    ...RUNTIME_WORKSPACE_CONNECTION_PROVIDERS.find((provider) => provider.id === id),
}));
export const workspaceConnectionProviderOverrides = WORKSPACE_CONNECTION_PROVIDERS;
function withLocalOverrides(overrides = []) {
    return [...workspaceConnectionProviderOverrides, ...overrides];
}
export function mergeWorkspaceConnectionProviders(overrides = []) {
    return mergeRuntimeWorkspaceConnectionProviders(withLocalOverrides(overrides));
}
export function listWorkspaceConnectionProviders(options = {}) {
    return listRuntimeWorkspaceConnectionProviders({
        ...options,
        providerOverrides: withLocalOverrides(options.providerOverrides),
    });
}
export function getWorkspaceConnectionProvider(id, overrides = []) {
    return getRuntimeWorkspaceConnectionProvider(id, withLocalOverrides(overrides));
}
export function listWorkspaceConnectionProvidersForTemplate(templateUse, providerOverrides = []) {
    return listWorkspaceConnectionProviders({ templateUse, providerOverrides });
}
export function listWorkspaceConnectionProvidersForCapability(capability, providerOverrides = []) {
    return listWorkspaceConnectionProviders({ capability, providerOverrides });
}
export function workspaceConnectionProviderSupports(providerOrId, capability) {
    const provider = typeof providerOrId === "string"
        ? getWorkspaceConnectionProvider(providerOrId)
        : providerOrId;
    return provider?.capabilities.includes(capability) ?? false;
}
